// Перебор идёт потоком, как в semanticSearch: текст чанка при просмотре не
// читается, вектор считается прямо из BLOB, в памяти живёт только top-N.
// Прежняя реализация материализовала всю выборку вместе с текстами, поэтому
// полный охват корпуса был ей не по силам и держался на потолке scanLimit.
func scanSyntaxHelperSearchTop(ctx context.Context, db *sql.DB, model string, scanLimit, limit int, queryVector []float64) ([]scoredChunk, int, error) {
	if limit <= 0 {
		limit = 10
	}
	statement := `
		SELECT c.id, e.vector
		FROM syntax_helper_embeddings e
		JOIN syntax_helper_chunks c ON c.id = e.chunk_id
		WHERE e.model = ?
		ORDER BY c.id`
	args := []any{model}
	if scanLimit > 0 {
		statement += `
		LIMIT ?`
		args = append(args, scanLimit)
	}
	rows, err := db.QueryContext(ctx, statement, args...)
	if err != nil {
		return nil, 0, fmt.Errorf("query syntax helper search candidates: %w", err)
	}
	defer rows.Close()

	queryNorm := vectorNorm(queryVector)
	top := make(scoredChunkHeap, 0, limit)
	scanned := 0
	for rows.Next() {
		var id int64
		var vectorBlob sql.RawBytes
		if err := rows.Scan(&id, &vectorBlob); err != nil {
			return nil, 0, fmt.Errorf("scan syntax helper search candidate: %w", err)
		}
		score, err := cosineSimilarityFromBlob(queryVector, queryNorm, vectorBlob)
		if err != nil {
			return nil, 0, err
		}
		scanned++
		candidate := scoredChunk{id: id, score: score}
		if len(top) < limit {
			heap.Push(&top, candidate)
			continue
		}
		if top.betterThanWorst(candidate) {
			top[0] = candidate
			heap.Fix(&top, 0)
		}
	}
	if err := rows.Err(); err != nil {
		return nil, 0, fmt.Errorf("iterate syntax helper search candidates: %w", err)
	}

	result := make([]scoredChunk, len(top))
	for i := len(top) - 1; i >= 0; i-- {
		result[i] = heap.Pop(&top).(scoredChunk)
	}
	return result, scanned, nil
}

func loadSyntaxHelperSearchItems(ctx context.Context, db *sql.DB, ranked []scoredChunk) ([]syntaxSemanticSearchItem, error) {
	if len(ranked) == 0 {
		return []syntaxSemanticSearchItem{}, nil
	}
	placeholders := make([]string, len(ranked))
	args := make([]any, len(ranked))
	for i, entry := range ranked {
		placeholders[i] = "?"
		args[i] = entry.id
	}
	rows, err := db.QueryContext(ctx, `
		SELECT c.id, c.source_kind, c.source_id, c.title, c.name_ru, c.name_en, c.kind,
			c.char_count, c.text_hash, c.text
		FROM syntax_helper_chunks c
		WHERE c.id IN (`+strings.Join(placeholders, ",")+`)
	`, args...)
	if err != nil {
		return nil, fmt.Errorf("query syntax helper search items: %w", err)
	}
	defer rows.Close()

	byID := make(map[int64]syntaxSemanticSearchItem, len(ranked))
	for rows.Next() {
		var item syntaxSemanticSearchItem
		if err := rows.Scan(&item.ID, &item.SourceKind, &item.SourceID, &item.Title, &item.NameRU, &item.NameEN,
			&item.Kind, &item.CharCount, &item.TextHash, &item.Text); err != nil {
			return nil, fmt.Errorf("scan syntax helper search item: %w", err)
		}
		item.Text = trimForJSON(item.Text, 2000)
		byID[item.ID] = item
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate syntax helper search items: %w", err)
	}

	result := make([]syntaxSemanticSearchItem, 0, len(ranked))
	for _, entry := range ranked {
		item, ok := byID[entry.id]
		if !ok {

			continue
		}
		item.Score = entry.score
		result = append(result, item)
	}
	return result, nil
}

