func handleSyntaxHelperSemanticSearch(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		query := queryParamRawFallback(r, "q")
		if query == "" {
			writeError(w, http.StatusBadRequest, "q is required")
			return
		}
		limit, err := queryInt(r.URL.Query().Get("limit"), 10)
		if err != nil || limit <= 0 {
			writeError(w, http.StatusBadRequest, "limit must be > 0")
			return
		}
		if limit > 100 {
			writeError(w, http.StatusBadRequest, "limit must be <= 100")
			return
		}

		scanLimit, err := queryInt(r.URL.Query().Get("scanLimit"), 0)
		if err != nil || scanLimit < 0 {
			writeError(w, http.StatusBadRequest, "scanLimit must be >= 0 (0 means the whole index)")
			return
		}
		cfg, err := loadActiveConfig()
		if err != nil {
			writeError(w, http.StatusInternalServerError, err.Error())
			return
		}
		model := r.URL.Query().Get("model")
		if model == "" {
			model = cfg.EmbeddingModel
		}
		if model == "" {
			writeError(w, http.StatusBadRequest, "model is required")
			return
		}
		if cfg.EmbeddingBaseURL == "" {
			writeError(w, http.StatusBadRequest, "embeddingBaseUrl is required in selected config")
			return
		}
		items, total, scanned, err := syntaxHelperSemanticSearch(r.Context(), db, cfg, query, model, limit, scanLimit)
		if err != nil {
			writeError(w, http.StatusInternalServerError, err.Error())
			return
		}
		writeJSON(w, http.StatusOK, syntaxSemanticSearchResponse{Query: query, Model: model, Total: total, Scanned: scanned, Limit: limit, Items: items})
	}
}

func scanStringRows(rows *sql.Rows) ([]string, error) {
	var result []string
	for rows.Next() {
		var value string
		if err := rows.Scan(&value); err != nil {
			return nil, err
		}
		result = append(result, value)
	}
	return result, rows.Err()
}

func syntaxNorm(value string) string {
	return strings.ToLower(strings.TrimSpace(value))
}

func syntaxBaseNorm(value string) string {
	value = syntaxNorm(value)
	if idx := strings.Index(value, ".<"); idx > 0 {
		return value[:idx]
	}
	if idx := strings.Index(value, "<"); idx > 0 {
		return strings.TrimRight(value[:idx], ".")
	}
	return value
}

func errorsIsNoRows(err error) bool {
	return err == sql.ErrNoRows
}
